import React, { useEffect, useRef, useState } from 'react';
import { View, Text, TextInput, TouchableOpacity, FlatList, Image, StyleSheet, Alert, Linking } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import * as ImagePicker from 'expo-image-picker';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { collection, query, orderBy, limit, onSnapshot, addDoc, deleteDoc, doc, setDoc, updateDoc, arrayUnion, serverTimestamp } from 'firebase/firestore';
import { auth, db } from '../config';
import { useTheme, BRAND } from '../constants/theme';
import { sendPush } from '../constants/push';

const CLOUD_NAME = 'faqfo0lu';
const UPLOAD_PRESET = 'flevora_upload';

const formatTime = (ts: any) => {
  const d = ts?.toDate ? ts.toDate() : null;
    return d ? d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '';
    };

    const formatLastSeen = (ts: any) => {
      const d = ts?.toDate ? ts.toDate() : null;
        if (!d) return 'Offline';
          const m = Math.floor((Date.now() - d.getTime()) / 60000);
            if (m < 1) return 'Last seen just now';
              if (m < 60) return `Last seen ${m}m ago`;
                return `Last seen ${Math.floor(m / 60)}h ago`;
                };

                export default function MessagesScreen() {
                  const router = useRouter();
                    const params = useLocalSearchParams<{ uid?: string; name?: string }>();
                      const { c } = useTheme();
                        const myUid = auth.currentUser?.uid || '';
                          const [tab, setTab] = useState<'chats' | 'requests'>('chats');
                            const [me, setMe] = useState<any>(null);
                              const [targetUid, setTargetUid] = useState(params.uid || '');
                                const [targetName, setTargetName] = useState(params.name || 'Chat');
                                  const [users, setUsers] = useState<any[]>([]);
                                    const [otherUser, setOtherUser] = useState<any>(null);
                                      const [msgs, setMsgs] = useState<any[]>([]);
                                        const [msgLimit, setMsgLimit] = useState(30);
                                          const [text, setText] = useState('');
                                            const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

                                              useEffect(() => {
                                                  if (params.uid) setTargetUid(params.uid);
                                                      if (params.name) setTargetName(params.name);
                                                        }, [params.uid, params.name]);

                                                          useEffect(() => {
                                                              const u1 = onSnapshot(collection(db, 'users'), (snap) => {
                                                                    setUsers(snap.docs.map((d) => ({ id: d.id, ...d.data() })).filter((u) => u.id !== myUid));
                                                                        });
                                                                            const u2 = myUid ? onSnapshot(doc(db, 'users', myUid), (s) => { if (s.exists()) setMe(s.data()); }) : () => {};
                                                                                return () => { u1(); u2(); };
                                                                                  }, [myUid]);

                                                                                    useEffect(() => {
                                                                                        if (!targetUid || !myUid) return;
                                                                                            const u1 = onSnapshot(doc(db, 'users', targetUid), (snap) => { if (snap.exists()) setOtherUser(snap.data()); });
                                                                                                const chatId = [myUid, targetUid].sort().join('_');
                                                                                                    const q = query(collection(db, 'conversations', chatId, 'messages'), orderBy('createdAt', 'desc'), limit(msgLimit));
                                                                                                        const u2 = onSnapshot(q, (snap) => {
                                                                                                              const list = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
                                                                                                                    setMsgs(list);
                                                                                                                          list.forEach((m: any) => {
                                                                                                                                  if (m.senderUid !== myUid && !m.read) {
                                                                                                                                            updateDoc(doc(db, 'conversations', chatId, 'messages', m.id), { read: true }).catch(() => {});
                                                                                                                                                    }
                                                                                                                                                          });
                                                                                                                                                              });
                                                                                                                                                                  return () => { u1(); u2(); };
                                                                                                                                                                    }, [targetUid, myUid, msgLimit]);

                                                                                                                                                                      const isBlockedEitherWay =
                                                                                                                                                                          (Array.isArray(me?.blockedUsers) && me.blockedUsers.includes(targetUid)) ||
                                                                                                                                                                              (Array.isArray(otherUser?.blockedUsers) && otherUser.blockedUsers.includes(myUid));

                                                                                                                                                                                const handleTyping = (val: string) => {
                                                                                                                                                                                    setText(val);
                                                                                                                                                                                        if (!myUid || !targetUid || isBlockedEitherWay) return;
                                                                                                                                                                                            updateDoc(doc(db, 'users', myUid), { typingTo: val.trim() ? targetUid : '' }).catch(() => {});
                                                                                                                                                                                                if (timerRef.current) clearTimeout(timerRef.current);
                                                                                                                                                                                                    timerRef.current = setTimeout(() => { updateDoc(doc(db, 'users', myUid), { typingTo: '' }).catch(() => {}); }, 2500);
                                                                                                                                                                                                      };

                                                                                                                                                                                                        const sendMsg = async (mediaUrl = '', mediaType = 'text') => {
                                                                                                                                                                                                            if (isBlockedEitherWay || !targetUid || (!text.trim() && !mediaUrl)) return;
                                                                                                                                                                                                                const chatId = [myUid, targetUid].sort().join('_');
                                                                                                                                                                                                                    const body = text.trim();
                                                                                                                                                                                                                        setText('');
                                                                                                                                                                                                                            updateDoc(doc(db, 'users', myUid), { typingTo: '' }).catch(() => {});
                                                                                                                                                                                                                                await setDoc(doc(db, 'conversations', chatId), { participants: [myUid, targetUid], updatedAt: serverTimestamp() }, { merge: true });
                                                                                                                                                                                                                                    await addDoc(collection(db, 'conversations', chatId, 'messages'), {
                                                                                                                                                                                                                                          senderUid: myUid, text: body, mediaUrl, mediaType, read: false, createdAt: serverTimestamp(),
                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                  if (otherUser?.expoPushToken) sendPush(otherUser.expoPushToken, 'New Message', body || 'Sent a photo/video');
                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                      const pickMedia = async () => {
                                                                                                                                                                                                                                                          if (isBlockedEitherWay) return;
                                                                                                                                                                                                                                                              const res = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images', 'videos'], quality: 0.7 });
                                                                                                                                                                                                                                                                  if (res.canceled || !res.assets[0]) return;
                                                                                                                                                                                                                                                                      const asset = res.assets[0];
                                                                                                                                                                                                                                                                          const type = asset.type === 'video' ? 'video' : 'image';
                                                                                                                                                                                                                                                                              const data = new FormData();
                                                                                                                                                                                                                                                                                  data.append('file', { uri: asset.uri, type: type === 'video' ? 'video/mp4' : 'image/jpeg', name: `dm_${Date.now()}` } as any);
                                                                                                                                                                                                                                                                                      data.append('upload_preset', UPLOAD_PRESET);
                                                                                                                                                                                                                                                                                          const xhr = new XMLHttpRequest();
                                                                                                                                                                                                                                                                                              xhr.open('POST', `https://api.cloudinary.com/v1_1/${CLOUD_NAME}/${type}/upload`);
                                                                                                                                                                                                                                                                                                  xhr.onload = () => {
                                                                                                                                                                                                                                                                                                        const json = JSON.parse(xhr.responseText);
                                                                                                                                                                                                                                                                                                              if (json.secure_url) sendMsg(json.secure_url, type);
                                                                                                                                                                                                                                                                                                                  };
                                                                                                                                                                                                                                                                                                                      xhr.send(data);
                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                          const handleDelete = (id: string, senderUid: string) => {
                                                                                                                                                                                                                                                                                                                              if (senderUid !== myUid) return;
                                                                                                                                                                                                                                                                                                                                  const chatId = [myUid, targetUid].sort().join('_');
                                                                                                                                                                                                                                                                                                                                      Alert.alert('Delete Message', 'Remove this message?', [
                                                                                                                                                                                                                                                                                                                                            { text: 'Cancel', style: 'cancel' },
                                                                                                                                                                                                                                                                                                                                                  { text: 'Delete', style: 'destructive', onPress: () => deleteDoc(doc(db, 'conversations', chatId, 'messages', id)) },
                                                                                                                                                                                                                                                                                                                                                      ]);
                                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                                          const acceptChat = (uid: string) => updateDoc(doc(db, 'users', myUid), { acceptedChats: arrayUnion(uid) });
                                                                                                                                                                                                                                                                                                                                                            const blockUser = (uid: string, name: string) => {
                                                                                                                                                                                                                                                                                                                                                                Alert.alert('Block User', `Block @${name}?`, [
                                                                                                                                                                                                                                                                                                                                                                      { text: 'Cancel', style: 'cancel' },
                                                                                                                                                                                                                                                                                                                                                                            { text: 'Block', style: 'destructive', onPress: async () => { await updateDoc(doc(db, 'users', myUid), { blockedUsers: arrayUnion(uid) }); setTargetUid(''); } },
                                                                                                                                                                                                                                                                                                                                                                                ]);
                                                                                                                                                                                                                                                                                                                                                                                  };

                                                                                                                                                                                                                                                                                                                                                                                    if (!targetUid) {
                                                                                                                                                                                                                                                                                                                                                                                        const known = new Set([...(me?.following || []), ...(me?.followers || []), ...(me?.acceptedChats || [])]);
                                                                                                                                                                                                                                                                                                                                                                                            const blocked = new Set(me?.blockedUsers || []);
                                                                                                                                                                                                                                                                                                                                                                                                const list = users.filter((u) => !blocked.has(u.id) && !(u.blockedUsers || []).includes(myUid) && (tab === 'chats' ? known.has(u.id) : !known.has(u.id)));

                                                                                                                                                                                                                                                                                                                                                                                                    return (
                                                                                                                                                                                                                                                                                                                                                                                                          <View style={[styles.container, { backgroundColor: c.background }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                  <View style={[styles.header, { borderBottomColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                            <TouchableOpacity onPress={() => router.back()}><Ionicons name="arrow-back" size={24} color={c.text} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                      <Text style={[styles.title, { color: c.text }]}>Messages</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                              </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                      <View style={[styles.tabRow, { borderBottomColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                {(['chats', 'requests'] as const).map((t) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <TouchableOpacity key={t} onPress={() => setTab(t)} style={[styles.tabBtn, tab === t && { borderBottomColor: BRAND, borderBottomWidth: 2 }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Text style={{ color: tab === t ? BRAND : c.muted, fontWeight: '700', textTransform: 'capitalize' }}>{t}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <FlatList
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          data={list}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    keyExtractor={(item) => item.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ListEmptyComponent={<Text style={{ textAlign: 'center', marginTop: 40, color: c.muted }}>No {tab} yet.</Text>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        renderItem={({ item }) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity style={[styles.userRow, { borderBottomColor: c.border }]} onPress={() => { setTargetUid(item.id); setTargetName(item.username || 'User'); }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <View style={styles.avatar}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Text style={styles.avatarTxt}>{(item.username || 'U')[0].toUpperCase()}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {item.isOnline && <View style={styles.onlineDot} />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={{ flex: 1 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Text style={[styles.uname, { color: c.text }]}>@{item.username || 'user'}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Text style={{ color: c.muted, fontSize: 12 }}>{item.isOnline ? 'Online now' : formatLastSeen(item.lastSeen)}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {tab === 'requests' ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <View style={{ flexDirection: 'row', gap: 6 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <TouchableOpacity style={styles.accBtn} onPress={() => acceptChat(item.id)}><Text style={{ color: '#fff', fontSize: 12, fontWeight: '700' }}>Accept</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity style={[styles.decBtn, { backgroundColor: c.input }]} onPress={() => blockUser(item.id, item.username)}><Text style={{ color: c.text, fontSize: 12 }}>Block</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) : <Ionicons name="chatbubble-outline" size={20} color={BRAND} />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const isTyping = !isBlockedEitherWay && otherUser?.typingTo === myUid;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={[styles.container, { backgroundColor: c.background }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <View style={[styles.header, { borderBottomColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <TouchableOpacity onPress={() => setTargetUid('')}><Ionicons name="arrow-back" size={24} color={c.text} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <View style={{ flex: 1 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Text style={[styles.title, { color: c.text }]}>@{otherUser?.username || targetName}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Text style={{ fontSize: 11, color: isTyping || otherUser?.isOnline ? '#10B981' : c.muted }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {isBlockedEitherWay ? 'Blocked' : isTyping ? 'Typing...' : otherUser?.isOnline ? 'Online' : formatLastSeen(otherUser?.lastSeen)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity onPress={() => blockUser(targetUid, otherUser?.username || targetName)}><Ionicons name="ban-outline" size={22} color="#EF4444" /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </View>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <FlatList
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  inverted
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          data={msgs}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  keyExtractor={(item) => item.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onEndReached={() => setMsgLimit((n) => n + 30)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onEndReachedThreshold={0.4}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          contentContainerStyle={{ padding: 14 }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  renderItem={({ item }) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const mine = item.senderUid === myUid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity onLongPress={() => handleDelete(item.id, item.senderUid)} style={[styles.bubble, mine ? styles.myBubble : [styles.theirBubble, { backgroundColor: c.input }]]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {item.mediaType === 'image' && <Image source={{ uri: item.mediaUrl }} style={styles.msgImg} />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {item.mediaType === 'video' && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity onPress={() => Linking.openURL(item.mediaUrl)} style={styles.vidTag}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Ionicons name="play-circle" size={20} color={mine ? '#fff' : BRAND} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Text style={{ color: mine ? '#fff' : c.text, fontWeight: '600' }}>Video (Tap to Play)</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {!!item.text && <Text style={{ color: mine ? '#fff' : c.text }}>{item.text}</Text>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Text style={[styles.tick, { color: mine ? '#E5E7EB' : c.muted }]}>{formatTime(item.createdAt)} {mine ? (item.read ? '✓✓' : '✓') : ''}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {isBlockedEitherWay ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={[styles.blockedBar, { borderTopColor: c.border, backgroundColor: c.card }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Text style={{ color: c.muted, fontSize: 13 }}>Messaging is unavailable for this user.</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <View style={[styles.inputBar, { borderTopColor: c.border, backgroundColor: c.background }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <TouchableOpacity onPress={pickMedia}><Ionicons name="attach" size={24} color={BRAND} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TextInput style={[styles.input, { backgroundColor: c.input, color: c.text }]} placeholder="Message..." placeholderTextColor={c.muted} value={text} onChangeText={handleTyping} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <TouchableOpacity onPress={() => sendMsg()}><Ionicons name="send" size={22} color={BRAND} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

